from kern import *

def bauen():
    einheit('geometrie.kreis')
    LP = 'M7 5 (Kreis)'
    # ---------------- umkehrung ----------------
    lz = 'umkehrung'
    A(lz, 'test', 'begruenden', None, 3, LP,
      'Im Dreieck ABC ist AB = 10 cm lang, und M ist der Mittelpunkt von AB. Die Strecke MC ist ebenfalls 5 cm lang. Welche Aussage über den Winkel γ bei C stimmt?',
      ['γ ist kleiner als 90°, denn C ist nur 5 cm von M entfernt und liegt deshalb innerhalb des Kreises um M durch A und B.',
       'γ = 60°, denn MC ist halb so lang wie AB.',
       'γ = 90°, denn C liegt auf dem Kreis um M mit Radius 5 cm durch A und B (Umkehrung des Satzes des Thales).',
       'Man kann über γ nichts sagen, denn es ist kein Winkel gegeben.'], 2,
      {0: 'MC = 5 cm ist genau der Radius des Kreises, also liegt C auf dem Kreis und nicht innerhalb.',
       1: 'Verwechselt mit dem gleichseitigen Dreieck; die Länge MC = AB : 2 sagt etwas anderes: C liegt auf dem Thaleskreis.',
       3: 'Übersieht, dass die Abstände MA = MB = MC = 5 cm schon genügen (Umkehrung des Satzes des Thales).'},
      'Der Kreis um M durch A und B hat den Radius MA = 5 cm. Wegen MC = 5 cm liegt C auf diesem Kreis. Nach der Umkehrung des Satzes des Thales ist dann γ = 90°.',
      'Die Übungen setzen den Satz des Thales vorwärts ein; hier muss aus gleich langen Strecken auf einen rechten Winkel geschlossen und die Alternativen begründet verworfen werden.')
    Z(lz, 'korrektur', 'umkehr', None, 2, LP,
      'Das Dreieck ABC hat die Eckpunkte A(−2 | 0), B(6 | 0) und C(2 | 4) (1 Einheit = 1 cm). Wie groß ist der Winkel bei C?',
      90, '90',
      [(45, '90 : 2', 'den Winkel bei A (oder B) angegeben: das Dreieck ist gleichschenklig-rechtwinklig, α = 45°'),
       (60, '180 : 3', 'wie bei einem gleichseitigen Dreieck gerechnet'),
       (180, '180', 'die Winkelsumme als Winkel bei C angegeben')],
      'Der Mittelpunkt von AB ist M(2 | 0), und MA = MB = 4 cm. Der Punkt C(2 | 4) hat von M den Abstand 4 cm. Also liegt C auf dem Kreis um M durch A und B, und nach der Umkehrung des Satzes des Thales ist γ = 90°.',
      'Der rechte Winkel wird aus Koordinaten über den Abstand zum Mittelpunkt erkannt; die Übungen nennen die Eigenschaft im Text.', '°')
    A(lz, 'korrektur', 'begruenden', None, 2, LP,
      'Die Strecke AB ist 8 cm lang, M ist ihr Mittelpunkt. Der Punkt C liegt nicht auf der Geraden AB. Bei welchem Abstand MC ist der Winkel ACB genau 90°?',
      ['MC = 3 cm', 'MC = 4 cm', 'MC = 5 cm', 'MC = 8 cm'], 1,
      {0: 'Bei MC = 3 cm liegt C innerhalb des Kreises um M mit Radius 4 cm, der Winkel bei C ist größer als 90°.',
       2: 'Bei MC = 5 cm liegt C außerhalb dieses Kreises, der Winkel bei C ist kleiner als 90°.',
       3: 'Bei MC = 8 cm liegt C weit außerhalb, der Winkel bei C ist kleiner als 90°.'},
      'Der Thaleskreis hat den Radius 8 cm : 2 = 4 cm. Genau für Punkte C auf diesem Kreis ist der Winkel bei C ein rechter. Innerhalb des Kreises ist der Winkel größer, außerhalb kleiner als 90°.',
      'Eine Abstandsbedingung wird als Lage zum Kreis gelesen (Umkehrung); die Übungen geben den Kreis schon vor.')
    L(lz, 'korrektur', 'fehler', 'fehler_detektiv', 2, LP,
      'Mia will zeigen, dass im Dreieck ABC mit AB = 10 cm der Winkel bei C ein rechter ist. Zeile 1: Sie zeichnet M als Mitte von AB. Zeile 2: Sie misst MC = 6 cm und sagt: „C liegt auf dem Kreis um M durch A und B.“ Zeile 3: Nach der Umkehrung des Satzes des Thales ist γ = 90°. In welcher Zeile steckt der Fehler, und wie groß ist der Radius des Kreises um M durch A und B (in cm)?',
      'Fehler in Zeile □, der Radius ist □ cm', [2, 5], ['2', '10 : 2'],
      [(2, 10, '10', 'die ganze Strecke AB statt der halben als Radius genommen'),
       (2, 6, '6', 'die gemessene Strecke MC als Radius genommen'),
       (1, 1, '1', 'Zeile 1 für falsch gehalten, obwohl M als Mitte von AB richtig eingezeichnet ist'),
       (2, 20, '10 · 2', 'den Durchmesser verdoppelt statt halbiert')],
      'Der Kreis durch A und B um M hat den Radius MA = 10 cm : 2 = 5 cm. Mit MC = 6 cm liegt C außerhalb dieses Kreises, also ist γ kleiner als 90°. Zeile 2 ist falsch, Zeile 3 folgt daraus nicht.',
      'Fehler-Detektiv bei der Umkehrung (Radius = halbe Strecke); die Übungen verwenden den Thaleskreis nur vorwärts.')
    A(lz, 'sicherung', 'parameter', None, 2, LP,
      'Gegeben sind A(0 | 0) und B(8 | 0). Welcher der Punkte C liegt so, dass das Dreieck ABC bei C einen rechten Winkel hat?',
      ['C(4 | 3)', 'C(4 | 4)', 'C(4 | 5)', 'C(2 | 4)'], 1,
      {0: 'Abstand von M(4 | 0) ist 3 cm, also kleiner als der Radius 4 cm: C liegt innerhalb des Thaleskreises, der Winkel ist stumpf.',
       2: 'Abstand von M(4 | 0) ist 5 cm, also größer als der Radius 4 cm: C liegt außerhalb, der Winkel ist spitz.',
       3: 'C(2 | 4) hat von M(4 | 0) den Abstand √20 ≈ 4,5 cm, das ist mehr als der Radius 4 cm; der Winkel ist spitz.'},
      'Der Mittelpunkt von AB ist M(4 | 0), der Thaleskreis hat den Radius 4. C(4 | 4) hat von M den Abstand 4 und liegt auf dem Kreis. Bei den anderen Punkten liegt C innerhalb (4 | 3) oder außerhalb (4 | 5) und (2 | 4).',
      'Welche von vier Lagen genau auf dem Kreis liegt, wird ohne Zeichnung entschieden; die Übungen liefern eine Skizze.')
    Z(lz, 'sicherung', 'parameter', None, 3, LP,
      'Gegeben sind A(0 | 0) und B(10 | 0). Wie viele Punkte C mit ganzzahligen Koordinaten und positiver y-Koordinate gibt es, für die das Dreieck ABC bei C einen rechten Winkel hat?',
      5, '1 + 2 + 2',
      [(10, '5 · 2', 'auch die Punkte mit negativer y-Koordinate mitgezählt'),
       (7, '5 + 2', 'die Punkte A und B (y = 0) mitgezählt'),
       (4, '5 − 1', 'den Punkt (5 | 5) über der Mitte vergessen')],
      'Der Thaleskreis hat den Mittelpunkt M(5 | 0) und den Radius 5. Gesucht sind ganzzahlige Punkte (x | y) mit y > 0 und (x − 5)² + y² = 25. y = 5: x = 5. y = 4: x = 2 oder 8. y = 3: x = 1 oder 9. y = 2 und y = 1 liefern keine ganzen x. Das sind 1 + 2 + 2 = 5 Punkte.',
      'Mehrere Lösungen der Umkehrung werden systematisch gesucht, Randfälle (y = 0, y < 0) ausdrücklich ausgeschlossen; die Übungen haben genau einen Punkt.')
    L(lz, 'sicherung', 'umkehr', 'umkehren', 3, LP,
      'M ist der Mittelpunkt der Strecke AB, und es gilt MA = MB = MC. Der Winkel bei A im Dreieck ABC beträgt 40°. Die Dreiecke AMC und MBC sind gleichschenklig. Wie groß sind der Winkel ACM, der Winkel MCB und der Winkel γ bei C?',
      'ACM = □°, MCB = □°, γ = □°', [40, 50, 90], ['40', '(180 − 80) : 2', '40 + 50'],
      [(2, 40, '40', 'den Winkel MCB gleich ACM gesetzt'),
       (2, 140, '180 − 40', 'die Winkelsumme minus 40° als Basiswinkel genommen'),
       (3, 80, '40 + 40', 'beide Basiswinkel gleich 40° angenommen'),
       (1, 50, '90 − 40', 'den Winkel bei B (50°) statt ACM angegeben')],
      'Im gleichschenkligen Dreieck AMC (MA = MC) ist der Winkel ACM = α = 40°. Der Winkel AMC ist 180° − 2 · 40° = 100°, also der Winkel CMB = 80°. Im gleichschenkligen Dreieck MBC ist MCB = (180° − 80°) : 2 = 50°. Damit γ = 40° + 50° = 90°.',
      'Der rechte Winkel wird aus MA = MB = MC hergeleitet (Umkehrung bewiesen, nicht zitiert); die Übungen geben den Satz an.')

    # ---------------- lage ----------------
    lz = 'lage'
    L(lz, 'test', 'parameter', None, 3, LP,
      'Ein Kreis um M hat den Radius 6 cm. Geraden haben von M die Abstände d = 0, 1, 2, …, 10 cm (elf Fälle, d ist jeweils eine ganze Zahl). In wie vielen Fällen ist die Gerade eine Sekante (zwei gemeinsame Punkte), in wie vielen eine Tangente, in wie vielen eine Passante (kein gemeinsamer Punkt)?',
      'Sekante in □ Fällen, Tangente in □ Fall(en), Passante in □ Fällen', [6, 1, 4], ['6', '1', '4'],
      [(1, 5, '5', 'den Fall d = 0 (Gerade durch den Mittelpunkt) nicht mitgezählt'),
       (1, 7, '6 + 1', 'den Tangentenfall d = 6 als Sekante mitgezählt'),
       (3, 5, '11 − 6', 'die Tangente nicht abgezogen: 11 − 6 Passanten'),
       (2, 0, '0', 'keinen Tangentenfall gefunden, weil der Radius nicht als Abstand vorkommt')],
      'Sekante: Abstand kleiner als der Radius, d = 0, 1, 2, 3, 4, 5, also 6 Fälle (auch d = 0, die Gerade durch M). Tangente: Abstand gleich dem Radius, d = 6, ein Fall. Passante: Abstand größer als der Radius, d = 7, 8, 9, 10, also 4 Fälle. Probe: 6 + 1 + 4 = 11.',
      'Alle drei Lagen werden über den Vergleich Abstand ↔ Radius an einer ganzen Zahlenreihe gezählt, mit den Grenzfällen d = 0 und d = r; die Übungen haben einen einzigen Abstand.')
    A(lz, 'korrektur', 'rueckwaerts', None, 2, LP,
      'Eine Gerade schneidet einen Kreis um M in genau zwei Punkten. Die Gerade hat vom Mittelpunkt M den Abstand 7 cm. Welche Aussage über den Radius r des Kreises stimmt?',
      ['r < 7 cm', 'r = 7 cm', 'r > 7 cm', 'r ≤ 7 cm'], 2,
      {0: 'Bei r < 7 cm hätte die Gerade keinen Punkt mit dem Kreis gemeinsam (Passante).',
       1: 'Bei r = 7 cm hätte die Gerade genau einen Punkt mit dem Kreis gemeinsam (Tangente).',
       3: 'r ≤ 7 cm schließt den Tangentenfall r = 7 cm ein; dann gäbe es nur einen oder keinen Punkt.'},
      'Zwei gemeinsame Punkte gibt es, wenn der Abstand der Geraden vom Mittelpunkt kleiner als der Radius ist: 7 cm < r. Bei r = 7 cm wäre die Gerade Tangente, bei kleinerem r Passante.',
      'Vom Ergebnis (zwei Schnittpunkte) wird auf den Radius geschlossen; die Übungen schließen vom Abstand auf die Anzahl.')
    Z(lz, 'korrektur', 'umkehr', None, 2, LP,
      'Eine Gerade g hat vom Mittelpunkt M den Abstand 3 cm. Ein Kreis um M soll die Gerade g nicht treffen. Sein Radius soll eine ganze Zahl in cm sein (größer als 0). Wie groß darf der Radius höchstens sein?',
      2, '3 − 1',
      [(3, '3', 'den Radius gleich dem Abstand gesetzt; dann wäre g Tangente und hätte einen Punkt mit dem Kreis gemeinsam'),
       (4, '3 + 1', 'wie bei einer Sekante gerechnet: Radius größer als der Abstand'),
       (1, '1', 'nur den kleinsten möglichen Radius genannt')],
      'Kein gemeinsamer Punkt heißt: Der Radius ist kleiner als der Abstand 3 cm. Die größte ganze Zahl kleiner als 3 ist 2. Bei r = 3 wäre g Tangente.',
      'Eine Bedingung (keine gemeinsamen Punkte) wird in eine Radiusgrenze mit Randfall übersetzt; die Übungen fragen nach der Anzahl der Punkte.', 'cm')
    L(lz, 'korrektur', 'darstellung', None, 2, LP,
      'Eine Gerade g hat vom Mittelpunkt M den Abstand 4 cm. Wie viele gemeinsame Punkte hat g mit einem Kreis um M, wenn dessen Radius 3 cm, 4 cm oder 5 cm beträgt?',
      'r = 3 cm: □ Punkte; r = 4 cm: □ Punkt(e); r = 5 cm: □ Punkte', [0, 1, 2], ['0', '1', '2'],
      [(1, 1, '1', 'bei r = 3 cm eine Berührung angenommen'),
       (2, 2, '2', 'bei r = 4 cm zwei Schnittpunkte angenommen, obwohl g Tangente ist'),
       (2, 0, '0', 'bei r = 4 cm keinen gemeinsamen Punkt angenommen'),
       (3, 1, '1', 'bei r = 5 cm nur einen Punkt angenommen')],
       'r = 3 cm < 4 cm: Die Gerade liegt außerhalb, 0 Punkte (Passante). r = 4 cm = Abstand: Tangente, 1 Punkt. r = 5 cm > 4 cm: Sekante, 2 Punkte.',
      'Derselbe Abstand wird mit drei Radien verglichen – wie der Kreis „wächst“ – statt mit einem festen Kreis.')
    A(lz, 'sicherung', 'begruenden', None, 2, LP,
      'Ein Kreis hat den Durchmesser 9 cm. Bei welchem Abstand d vom Mittelpunkt ist eine Gerade eine Tangente?',
      ['d = 9 cm', 'd = 4,5 cm', 'd = 2,25 cm', 'd = 0 cm'], 1,
      {0: 'Den Durchmesser als Abstand genommen; der Abstand muss gleich dem Radius sein.',
       2: 'Den Radius noch einmal halbiert.',
       3: 'Eine Gerade durch den Mittelpunkt schneidet den Kreis in zwei Punkten.'},
      'Tangente heißt: Der Abstand der Geraden vom Mittelpunkt ist gleich dem Radius. Der Radius ist 9 cm : 2 = 4,5 cm.',
      'Der Radius muss erst aus dem Durchmesser gewonnen werden, bevor Abstand und Radius verglichen werden; die Übungen geben den Radius an.')
    L(lz, 'sicherung', 'transfer', 'anwenden', 3, LP,
      'Zwei Kreise haben denselben Mittelpunkt M. Der kleine hat den Radius 3 cm, der große den Radius 7 cm. Eine Gerade g hat von M den Abstand d. Wie viele gemeinsame Punkte hat g insgesamt mit beiden Kreisen zusammen, wenn d = 3 cm, d = 5 cm oder d = 7 cm ist?',
      'd = 3 cm: □; d = 5 cm: □; d = 7 cm: □', [3, 2, 1], ['1 + 2', '0 + 2', '0 + 1'],
      [(1, 2, '0 + 2', 'bei d = 3 cm den Berührpunkt des kleinen Kreises vergessen'),
       (2, 1, '0 + 1', 'bei d = 5 cm die Gerade als Tangente des großen Kreises gesehen'),
       (3, 2, '1 + 1', 'bei d = 7 cm einen zweiten Punkt vom kleinen Kreis dazugezählt'),
       (2, 4, '2 + 2', 'bei d = 5 cm beide Kreise als geschnitten gezählt')],
      'd = 3 cm: kleiner Kreis (Radius 3): Tangente, 1 Punkt; großer Kreis (Radius 7): Sekante, 2 Punkte; zusammen 3. d = 5 cm: kleiner Kreis: Passante, 0; großer Kreis: Sekante, 2; zusammen 2. d = 7 cm: kleiner Kreis: 0; großer Kreis: Tangente, 1; zusammen 1.',
      'Zwei Kreise mit verschiedenen Radien werden gleichzeitig beurteilt; die Übungen haben einen Kreis.')
    A(lz, 'sicherung', 'begruenden', None, 3, LP,
      'Eine Gerade g geht nicht durch den Mittelpunkt M. Mia sagt: „Je größer der Radius eines Kreises um M ist, desto mehr gemeinsame Punkte hat er mit g.“ Welche Antwort mit Begründung stimmt?',
      ['Richtig: Ein größerer Kreis hat mehr Punkte, also schneidet er die Gerade öfter.',
       'Falsch: Die Anzahl ist höchstens 2. Sie ist 0, solange r kleiner als der Abstand von g zu M ist, 1 bei r gleich dem Abstand und 2, sobald r größer ist.',
       'Falsch: Die Anzahl ist für jeden Radius gleich, denn die Gerade ändert sich nicht.',
       'Falsch: Mit wachsendem Radius nimmt die Anzahl wieder ab, weil der Kreis die Gerade irgendwann nicht mehr berührt.'], 1,
      {0: 'Die Zahl der Punkte eines Kreises ist nicht entscheidend; eine Gerade schneidet einen Kreis in höchstens zwei Punkten.',
       2: 'Die Anzahl hängt vom Vergleich Radius ↔ Abstand ab und ändert sich mit dem Radius.',
       3: 'Ist der Radius einmal größer als der Abstand, bleibt es bei zwei Schnittpunkten; sie verschwinden nicht wieder.'},
      'Es gibt drei Fälle je nach Radius r und Abstand d (d > 0): r < d: kein gemeinsamer Punkt; r = d: ein Punkt (Tangente); r > d: zwei Punkte (Sekante). Mehr als zwei Punkte sind nie möglich.',
      'Die Abhängigkeit der Punktzahl vom Radius wird begründet, einschließlich der Obergrenze 2; die Übungen rechnen mit festen Werten.')

    # ---------------- umkreis_inkreis ----------------
    lz = 'umkreis_inkreis'
    A(lz, 'test', 'begruenden', None, 3, LP,
      'Bei welchem Dreieck liegt der Mittelpunkt des Umkreises außerhalb des Dreiecks? Wähle die Antwort mit richtiger Begründung.',
      ['Dreieck mit 50°, 60°, 70°, denn alle Winkel sind kleiner als 90°.',
       'Dreieck mit 40°, 40°, 100°, denn es hat einen stumpfen Winkel.',
       'Dreieck mit 45°, 45°, 90°, denn bei einem rechten Winkel liegt der Mittelpunkt außerhalb.',
       'Dreieck mit 30°, 60°, 90°, denn alle Seiten sind verschieden lang.'], 1,
      {0: 'Bei einem spitzwinkligen Dreieck (alle Winkel unter 90°) liegt der Umkreismittelpunkt innerhalb.',
       2: 'Bei einem rechten Winkel liegt der Mittelpunkt in der Mitte der Hypotenuse, also auf dem Rand.',
       3: 'Die Seitenlängen entscheiden nicht; bei 30°, 60°, 90° liegt der Mittelpunkt auf der Hypotenuse.'},
      'Spitzwinklig (alle Winkel < 90°): Mittelpunkt innerhalb. Rechtwinklig: Mittelpunkt in der Mitte der Hypotenuse. Stumpfwinklig (ein Winkel > 90°): Mittelpunkt außerhalb. Nur das Dreieck mit 40°, 40°, 100° ist stumpfwinklig.',
      'Die Lage des Umkreismittelpunkts wird mit der Winkelart begründet; die Übungen fragen die Lage bei einem einzigen Dreieck.')
    A(lz, 'korrektur', 'begruenden', None, 2, LP,
      'Welche Aussage über den Mittelpunkt des Umkreises eines Dreiecks ist richtig?',
      ['Er ist der Schnittpunkt der Winkelhalbierenden, denn er muss von den drei Seiten gleich weit entfernt sein.',
       'Er ist der Schnittpunkt der Mittelsenkrechten, denn er muss von den drei Ecken gleich weit entfernt sein.',
       'Er ist der Schnittpunkt der Mittelsenkrechten, denn er muss von den drei Seiten gleich weit entfernt sein.',
       'Er ist der Schnittpunkt der Winkelhalbierenden, denn er muss von den drei Ecken gleich weit entfernt sein.'], 1,
      {0: 'Das beschreibt den Inkreismittelpunkt: Er ist von den drei Seiten gleich weit entfernt.',
       2: 'Die Mittelsenkrechten sichern gleichen Abstand zu den Ecken, nicht zu den Seiten.',
       3: 'Winkelhalbierende sichern gleichen Abstand zu den Seiten, nicht zu den Ecken.'},
      'Der Umkreis geht durch alle drei Ecken, sein Mittelpunkt ist daher von A, B und C gleich weit entfernt. Alle Punkte, die von A und B gleich weit entfernt sind, liegen auf der Mittelsenkrechten von AB. Der Inkreis dagegen berührt die drei Seiten; sein Mittelpunkt liegt auf den Winkelhalbierenden.',
      'Umkreis und Inkreis werden über die Abstandseigenschaft unterschieden, nicht nur über ihre Namen; die Übungen konstruieren.')
    L(lz, 'korrektur', 'darstellung', None, 2, LP,
      'Liegt der Mittelpunkt des Umkreises innerhalb des Dreiecks (1), auf einer Seite (2) oder außerhalb (3)? Trage für drei Dreiecke die Zahl 1, 2 oder 3 ein: Dreieck A (35°, 75°, 70°), Dreieck B (30°, 60°, 90°), Dreieck C (25°, 40°, 115°).',
      'A: □; B: □; C: □', [1, 2, 3], ['1', '2', '3'],
      [(1, 2, '2', 'beim spitzwinkligen Dreieck A eine Seite statt innen gewählt'),
       (2, 1, '1', 'beim rechtwinkligen Dreieck B den Mittelpunkt im Inneren gesehen'),
       (3, 2, '2', 'beim stumpfwinkligen Dreieck C nur „nicht innen“ gedacht, aber die Seite gewählt'),
       (3, 1, '1', 'beim stumpfwinkligen Dreieck C alle Dreiecke wie A behandelt')],
      'A: alle Winkel unter 90°, Mittelpunkt innerhalb (1). B: ein rechter Winkel, Mittelpunkt in der Mitte der Hypotenuse (2). C: ein stumpfer Winkel (115°), Mittelpunkt außerhalb (3).',
      'Drei Winkelarten nebeneinander; die Übungen untersuchen eine Winkelart.')
    L(lz, 'korrektur', 'fehler', 'fehler_detektiv', 2, LP,
      'Ben will den Inkreis eines Dreiecks mit den Seiten 7 cm, 8 cm und 9 cm konstruieren. Zeile 1: Der Mittelpunkt des Inkreises muss von allen drei Seiten gleich weit entfernt sein. Zeile 2: Deshalb konstruiert er die Mittelsenkrechten der drei Seiten. Zeile 3: Ihr Schnittpunkt ist der Mittelpunkt des Inkreises. In welcher Zeile steckt der erste Fehler, und was muss er stattdessen konstruieren (1 = Winkelhalbierende, 2 = Mittelsenkrechten, 3 = Höhen)?',
      'Fehler in Zeile □, richtig sind die □', [2, 1], ['2', '1'],
      [(2, 2, '2', 'bei den Mittelsenkrechten geblieben, die den Umkreis liefern'),
       (2, 3, '3', 'die Höhen genannt, die ein ganz anderer Schnittpunkt sind'),
       (1, 1, '1', 'Zeile 1 für falsch gehalten, obwohl die Eigenschaft des Inkreises richtig beschrieben ist'),
       (1, 3, '3', 'den Folgefehler in Zeile 3 für den ersten Fehler gehalten')],
      'Zeile 1 stimmt. Gleicher Abstand zu zwei Seiten bedeutet: Der Punkt liegt auf der Winkelhalbierenden des Winkels zwischen den Seiten. Der Inkreismittelpunkt ist daher der Schnittpunkt der Winkelhalbierenden. Die Mittelsenkrechten liefern den Umkreismittelpunkt.',
      'Fehler-Detektiv, der Umkreis- und Inkreiskonstruktion verwechselt; die Übungen konstruieren eines von beiden.')
    A(lz, 'sicherung', 'begruenden', None, 2, LP,
      'Warum liegt der Mittelpunkt des Umkreises eines rechtwinkligen Dreiecks genau in der Mitte der Hypotenuse?',
      ['Weil die Hypotenuse die längste Seite ist und der Mittelpunkt immer auf der längsten Seite liegt.',
       'Weil der Mittelpunkt immer innerhalb des Dreiecks liegen muss, und die Mitte der Hypotenuse am weitesten innen ist.',
       'Weil nach der Umkehrung des Satzes des Thales der rechte Winkel auf dem Kreis mit Durchmesser AB liegt; die Mitte von AB ist dann von A, B und C gleich weit entfernt.',
       'Weil der Umkreis eines Dreiecks immer durch die Mitten der Seiten geht.'], 2,
      {0: 'Bei einem spitzwinkligen Dreieck liegt der Mittelpunkt innerhalb, nicht auf der längsten Seite.',
       1: 'Der Mittelpunkt liegt nur bei spitzwinkligen Dreiecken innerhalb; bei rechtwinkligen auf dem Rand, bei stumpfwinkligen außerhalb.',
       3: 'Der Umkreis geht durch die Ecken, nicht durch die Seitenmitten.'},
      'Der Thaleskreis über der Hypotenuse AB geht durch C, weil der Winkel bei C ein rechter ist (Umkehrung des Satzes des Thales). Also ist er der Umkreis, und sein Mittelpunkt ist die Mitte M von AB mit MA = MB = MC.',
      'Begründung über die Umkehrung des Satzes des Thales statt Faustregel; die Übungen nennen die Lage nur.')
    Z(lz, 'sicherung', 'parameter', None, 3, LP,
      'Ein Dreieck hat den Winkel α = 40° und einen Winkel β, dessen Größe eine ganze Zahl in Grad ist (β ≥ 1, γ ≥ 1). Für wie viele Werte von β liegt der Umkreismittelpunkt im Inneren des Dreiecks (nicht auf dem Rand)?',
      39, '89 − 51 + 1',
      [(38, '89 − 51', 'bei der Anzahl der ganzen Zahlen von 51 bis 89 das Plus 1 vergessen'),
       (41, '90 − 50 + 1', 'die Randfälle β = 50 (γ = 90°) und β = 90 mitgezählt'),
       (40, '90 − 50', 'die Grenzen β = 50 oder β = 90 mitgezählt')],
      'γ = 180° − 40° − β = 140° − β. Innen liegt der Mittelpunkt genau dann, wenn alle Winkel kleiner als 90° sind. β < 90° und γ < 90° (also β > 50°). Also β = 51, 52, …, 89. Das sind 89 − 51 + 1 = 39 Werte. Bei β = 50° oder β = 90° ist ein Winkel 90°, der Mittelpunkt liegt dann auf dem Rand.',
      'Eine Winkelbedingung wird in eine Zahl von Werten übersetzt, mit zwei Randfällen; die Übungen haben genau ein Dreieck.')
